package com.cornspies.fusionfactions.registry;

import java.util.EnumMap;
import java.util.Map;

import com.cornspies.fusionfactions.FusionFactions;
import com.cornspies.fusionfactions.industry.Machine;

import net.minecraft.core.registries.Registries;
import net.minecraft.sounds.SoundEvent;
import net.neoforged.neoforge.registries.DeferredHolder;
import net.neoforged.neoforge.registries.DeferredRegister;

// The mod's sound events. The sound files and sounds.json are generated by tools/sound_effects.py.
public final class ModSounds {
    public static final DeferredRegister<SoundEvent> SOUND_EVENTS = DeferredRegister.create(Registries.SOUND_EVENT, FusionFactions.MODID);

    public static final DeferredHolder<SoundEvent, SoundEvent> PISTOL_FIRE = register("weapon.pistol.fire");
    public static final DeferredHolder<SoundEvent, SoundEvent> AUTO_PISTOL_FIRE = register("weapon.auto_pistol.fire");
    public static final DeferredHolder<SoundEvent, SoundEvent> SMG_FIRE = register("weapon.smg.fire");
    public static final DeferredHolder<SoundEvent, SoundEvent> SHOTGUN_FIRE = register("weapon.shotgun.fire");
    public static final DeferredHolder<SoundEvent, SoundEvent> SNIPER_RIFLE_FIRE = register("weapon.sniper_rifle.fire");
    public static final DeferredHolder<SoundEvent, SoundEvent> GATLING_GUN_FIRE = register("weapon.gatling_gun.fire");
    public static final DeferredHolder<SoundEvent, SoundEvent> GATLING_GUN_SPIN = register("weapon.gatling_gun.spin");
    public static final DeferredHolder<SoundEvent, SoundEvent> WEAPON_EMPTY = register("weapon.empty");
    public static final DeferredHolder<SoundEvent, SoundEvent> WEAPON_RELOAD = register("weapon.reload");
    public static final DeferredHolder<SoundEvent, SoundEvent> WEAPON_RELOAD_DONE = register("weapon.reload_done");
    // Hit markers, played only to the shooter.
    public static final DeferredHolder<SoundEvent, SoundEvent> WEAPON_HIT = register("weapon.hit");
    public static final DeferredHolder<SoundEvent, SoundEvent> WEAPON_HEADSHOT = register("weapon.headshot");
    // Missiles (DESIGN.md §6.5).
    public static final DeferredHolder<SoundEvent, SoundEvent> MISSILE_LAUNCH = register("missile.launch");
    public static final DeferredHolder<SoundEvent, SoundEvent> MISSILE_INCOMING = register("missile.incoming");
    public static final DeferredHolder<SoundEvent, SoundEvent> MISSILE_EXPLODE = register("missile.explode");
    public static final DeferredHolder<SoundEvent, SoundEvent> MISSILE_EMP = register("missile.emp");
    public static final DeferredHolder<SoundEvent, SoundEvent> MISSILE_SHOT_DOWN = register("missile.shot_down");
    // Counterplay (DESIGN.md §6.9).
    public static final DeferredHolder<SoundEvent, SoundEvent> RADAR_ALERT = register("radar.alert");
    public static final DeferredHolder<SoundEvent, SoundEvent> INTERCEPTOR_LAUNCH = register("interceptor.launch");

    // Rocket launcher and lock warning (DESIGN.md §6b.6, §6b.7). The tones are played by the client to the shooter
    // and to a target with warning gear only.
    public static final DeferredHolder<SoundEvent, SoundEvent> ROCKET_LAUNCHER_FIRE = register("weapon.rocket_launcher.fire");
    public static final DeferredHolder<SoundEvent, SoundEvent> ROCKET_EXPLODE = register("weapon.rocket.explode");
    public static final DeferredHolder<SoundEvent, SoundEvent> LOCK_SEEKING = register("lock.seeking");
    public static final DeferredHolder<SoundEvent, SoundEvent> LOCK_LOCKED = register("lock.locked");
    public static final DeferredHolder<SoundEvent, SoundEvent> WARNING_SEEKING = register("warning.seeking");
    public static final DeferredHolder<SoundEvent, SoundEvent> WARNING_LOCKED = register("warning.locked");
    public static final DeferredHolder<SoundEvent, SoundEvent> WARNING_INCOMING = register("warning.incoming");
    // A rocket's motor in flight (guided and interceptor rockets), looped by the client while the rocket exists.
    public static final DeferredHolder<SoundEvent, SoundEvent> ROCKET_FLY = register("rocket.fly");

    public static final DeferredHolder<SoundEvent, SoundEvent> DESIGNATOR_MARK = register("designator.mark");
    public static final DeferredHolder<SoundEvent, SoundEvent> SILO_FORM_LAYER = register("silo.form_layer");
    public static final DeferredHolder<SoundEvent, SoundEvent> SILO_FORMED = register("silo.formed");
    public static final DeferredHolder<SoundEvent, SoundEvent> SILO_UNFORMED = register("silo.unformed");
    public static final DeferredHolder<SoundEvent, SoundEvent> SUPPLY_CRATE_LAND = register("supply_crate.land");

    // Loops the client plays while a block works (its LIT state is on).
    public static final Map<Machine, DeferredHolder<SoundEvent, SoundEvent>> MACHINE_RUNNING = new EnumMap<>(Machine.class);
    public static final DeferredHolder<SoundEvent, SoundEvent> GENERATOR_RUNNING = register("combustion_generator.running");
    public static final DeferredHolder<SoundEvent, SoundEvent> CHARGING_STATION_RUNNING = register("charging_station.running");

    static {
        for (Machine machine : Machine.values()) {
            MACHINE_RUNNING.put(machine, register("machine." + machine.id()));
        }
    }

    private static DeferredHolder<SoundEvent, SoundEvent> register(String name) {
        return SOUND_EVENTS.register(name, id -> SoundEvent.createVariableRangeEvent(id));
    }

    private ModSounds() {
    }
}
